{
    "testCases": [
        {
            "group": "Null Input String",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "executionContext",
                            "value": "new ExecutionContext()"
                        },
                        {
                            "parameter": "input",
                            "value": "null"
                        },
                        {
                            "parameter": "inputFormat",
                            "value": "InputFormat.JSON"
                        },
                        {
                            "parameter": "validate",
                            "value": "true"
                        }
                    ],
                    "expected": "NullPointerException",
                    "description": "When the input string is null the deserialization step should throw a NullPointerException (or a wrapped SchemaException). This validates the null‑check on the raw input."
                }
            ]
        },
        {
            "group": "Empty Input String",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "executionContext",
                            "value": "new ExecutionContext()"
                        },
                        {
                            "parameter": "input",
                            "value": "\"\""
                        },
                        {
                            "parameter": "inputFormat",
                            "value": "InputFormat.JSON"
                        },
                        {
                            "parameter": "validate",
                            "value": "true"
                        }
                    ],
                    "expected": "JsonSchemaException (or ValidationResult with errors)",
                    "description": "An empty string is not valid JSON; the deserialize method should raise an exception which propagates as a JsonSchemaException or results in a ValidationResult containing error messages."
                }
            ]
        },
        {
            "group": "Valid JSON Array – Validate true",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "executionContext",
                            "value": "new ExecutionContext()"
                        },
                        {
                            "parameter": "input",
                            "value": "\"[\\\"a\\\",\\\"b\\\",\\\"c\\\"]\""
                        },
                        {
                            "parameter": "inputFormat",
                            "value": "InputFormat.JSON"
                        },
                        {
                            "parameter": "validate",
                            "value": "true"
                        }
                    ],
                    "expected": "ValidationResult with isSuccess() == true",
                    "description": "A correctly formed JSON array should deserialize without error and, assuming the schema does not restrict the root type, validation succeeds."
                }
            ]
        },
        {
            "group": "Valid YAML Input – Validate false",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "executionContext",
                            "value": "new ExecutionContext()"
                        },
                        {
                            "parameter": "input",
                            "value": "\"- item1\\n- item2\\n- item3\""
                        },
                        {
                            "parameter": "inputFormat",
                            "value": "InputFormat.YAML"
                        },
                        {
                            "parameter": "validate",
                            "value": "false"
                        }
                    ],
                    "expected": "ValidationResult with isSuccess() == true (no validation performed)",
                    "description": "YAML list input should be deserialized correctly; with validate=false the walk should succeed without applying schema rules."
                }
            ]
        },
        {
            "group": "Unicode Characters in JSON – Validate true",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "executionContext",
                            "value": "new ExecutionContext()"
                        },
                        {
                            "parameter": "input",
                            "value": "\"{\\\"greeting\\\":\\\"こんにちは\\\"}\""
                        },
                        {
                            "parameter": "inputFormat",
                            "value": "InputFormat.JSON"
                        },
                        {
                            "parameter": "validate",
                            "value": "true"
                        }
                    ],
                    "expected": "ValidationResult with isSuccess() == true",
                    "description": "JSON containing Unicode characters must be handled by the deserializer and validated successfully."
                }
            ]
        },
